<script lang="ts">
  import API from "$lib/API";
  import { onMount, onDestroy } from "svelte";
  import { toast } from "svelte-sonner";
  import { useReader } from "./context.svelte";
  import { localLibraryState, saveProgress, message, canSaveLocalProgress } from "$localLibrary/library";
  import { createLibraryActionOwner } from "$localLibrary/action-owner";
  import { nativeAuthority } from "$platform/mutation-authority";
  import { requireMutationAcknowledgement, reportCurrentMutationFailure } from "$platform/mutation-feedback";
  const reader = useReader();
  const historyOwner = createLibraryActionOwner(() => JSON.stringify([reader.chapter?.id, reader.chapter?.relationships.manga.id]));
  let disposed = false, progressToken = "", timer = 0;
  type ProgressIntent = ReturnType<typeof historyOwner.capture>;
  let queued: { manga: string; chapter: string; page: number; completed: boolean; intent: ProgressIntent } | undefined;
  const flush = (finalPreviouslyAdmittedPage = false) => {
    const pending = queued; queued = undefined;
    if (!pending) return;
    // Exit may finish the immutable page action already admitted while live;
    // it never discovers a different account/mode after destruction.
    const assert = finalPreviouslyAdmittedPage ? pending.intent.assertDestination : pending.intent.assert;
    try { assert(); } catch { return; }
    void saveProgress(pending.manga, pending.chapter, pending.page, pending.completed, assert).catch(error => { if (!disposed) toast.error("Progress save failed", { description: message(error) }); });
  };
  onDestroy(() => { window.clearTimeout(timer); flush(true); disposed = true; });
  onMount(() => {
    const intent = historyOwner.capture();
    void intent.open().catch(error => { if (intent.alive()) toast.error("Local library unavailable", { description: message(error) }); });
  });
  let accountReadToken = "";
  $effect(() => {
    const actor = $nativeAuthority.actor, epoch = $nativeAuthority.epoch, chapter = reader.chapter;
    if (disposed || !$localLibraryState.ready || $localLibraryState.mode !== "account" || !actor || !chapter) return;
    const mangaId = chapter.relationships.manga.id, chapterId = chapter.id, token = JSON.stringify([actor, epoch, mangaId, chapterId]);
    if (token === accountReadToken) return;
    // A still-mounted reader can admit initial identity readiness, but a
    // destroyed callback cannot select that later identity. Harmless Session
    // data refreshes do not issue another history POST.
    const intent = historyOwner.capture(); accountReadToken = token;
    void intent.open().then(async context => {
      intent.assert();
      const response = await API.ChapterHistory.UpdateBatch(mangaId, { read_ids: [chapterId] }, { context, assert: intent.assert });
      intent.assert();
      requireMutationAcknowledgement(response, 200, true);
    }).catch(error => reportCurrentMutationFailure("History save failed", error, intent.alive));
  });
  $effect(() => {
    if (disposed || !$localLibraryState.ready || $localLibraryState.mode !== "device" || !canSaveLocalProgress($localLibraryState) || !reader.chapter || !reader.currentPage) return;
    const chapter = reader.chapter, page = reader.currentPage.index + 1;
    const completed = reader.isViewingLastPage || reader.currentPage.index === reader.pages.length - 1;
    const intent = historyOwner.capture();
    const token = JSON.stringify([intent.destinationKey, chapter.id, page, completed]);
    if (token === progressToken) return;
    progressToken = token; window.clearTimeout(timer);
    queued = { manga: chapter.relationships.manga.id, chapter: chapter.id, page, completed, intent };
    timer = window.setTimeout(() => flush(), 350);
  });
</script>
